## Teste dev: diagnose de colisões no bowl via raycast.

var main: Node3D
var t := 0.0
var started := false
var done := false


func _init() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS


func _ready() -> void:
	main = load("res://scenes/main.tscn").instantiate()
	add_child(main)


func _process(delta: float) -> void:
	t += delta
	if not started and t > 0.4:
		started = true
		main._start_game()
	if not started or done or t < 1.0:
		return
	done = true
	var space := main.get_world_3d().direct_space_state
	var center := Vector3(-180, 0, 80)
	for off in [36.0, 30.0, 20.0, 0.0, -20.0, -34.0]:
		for y0 in [2.0, -1.0, -3.0]:
			var from := center + Vector3(0, y0, off)
			var q := PhysicsRayQueryParameters3D.create(from, from + Vector3(0, -8, 0))
			var hit := space.intersect_ray(q)
			if hit.has("position"):
				var c: Object = hit.get("collider")
				var info := "z=%.0f y0=%.0f hit=(%.1f,%.1f,%.1f) obj=%s pos=%s" % [off + 80.0, y0, hit.position.x, hit.position.y, hit.position.z, c.get_class(), str((c as Node3D).global_position)]
				if c is CollisionShape3D:
					var cs := c as CollisionShape3D
					info += " shape=%s size?=%s parent_basis=%s" % [cs.shape.get_class(), str((cs.shape as BoxShape3D).size if cs.shape is BoxShape3D else Vector3.ZERO), str((cs.get_parent() as Node3D).basis)]
				print(info)
			else:
				print("z=%.0f y0=%.0f: nothing below" % [off + 80.0, y0])
	get_tree().quit()

