	var floor_m := MeshInstance3D.new()
	var fm := CylinderMesh.new()
	fm.top_radius = floor_r
	fm.bottom_radius = floor_r
	fm.height = 0.4
	floor_m.mesh = fm
	floor_m.material_override = m_concrete2
	fbody.add_child(floor_m)
	add_child(fbody)
